sources.content:
# Create a random name for the resource group
resource "random_pet" "rg_name" {
  prefix = var.resource_group_name_prefix
}

# Create a resource group
resource "azurerm_resource_group" "rg" {
  location = var.resource_group_location
  name     = random_pet.rg_name.id
}

# Create a random name for the Elastic SAN
resource "random_string" "elastic_san_name" {
  length  = 8
  special = false
  upper   = false
  lower   = true
  numeric = false
}

# Create Elastic SAN
resource "azurerm_elastic_san" "example" {
  name                = coalesce(var.elastic_san_name, "san-${random_string.elastic_san_name.result}")
  resource_group_name = azurerm_resource_group.rg.name
  location            = azurerm_resource_group.rg.location
  base_size_in_tib    = var.elastic_san_base_size_in_tib

  sku {
    name = var.elastic_san_sku_name
  }
}

# Create Elastic SAN Volume Group
resource "azurerm_elastic_san_volume_group" "example" {
  name           = coalesce(var.elastic_san_volume_group_name, "vg-${random_string.elastic_san_name.result}")
  elastic_san_id = azurerm_elastic_san.example.id
}

# Create Elastic SAN Volume
resource "azurerm_elastic_san_volume" "volume" {
  name            = coalesce(var.elastic_san_volume_name, "volume-${random_string.elastic_san_name.result}")
  volume_group_id = azurerm_elastic_san_volume_group.example.id
  size_in_gib     = var.elastic_san_volume_size_in_gib
}

output "resource_group_name" {
  value = azurerm_resource_group.rg.name
}

output "elastic_san_name" {
  value = azurerm_elastic_san.example.name
}

output "elastic_san_volume_group_name" {
  value = azurerm_elastic_san_volume_group.example.name
}

output "elastic_san_volume_name" {
  value = azurerm_elastic_san_volume.volume.name
}

output "elastic_san_volume_id" {
  value = azurerm_elastic_san_volume.volume.id
}

terraform {
  required_providers {
    azurerm = {
      source  = "hashicorp/azurerm"
      version = "~>4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~>3.0"
    }
  }
}

provider "azurerm" {
  features {}
}

variable "resource_group_location" {
  type        = string
  default     = "eastus"
  description = "Location of the resource group."
}

variable "resource_group_name_prefix" {
  type        = string
  default     = "rg"
  description = "Prefix of the resource group name that's combined with a random ID so name is unique in your Azure subscription."
}

variable "elastic_san_name" {
  type        = string
  default     = ""
  description = "Name of the Elastic SAN. Name is partially randomized if blank."
}

variable "elastic_san_volume_group_name" {
  type        = string
  default     = ""
  description = "Name of the Elastic SAN volume group. Name is partially randomized if blank."
}

variable "elastic_san_volume_name" {
  type        = string
  default     = ""
  description = "Name of the Elastic SAN volume. Name is partially randomized if blank."
}

variable "elastic_san_sku_name" {
  type        = string
  default     = "Premium_LRS"
  description = "The SKU name of the Elastic SAN."
}

variable "elastic_san_base_size_in_tib" {
  type        = number
  default     = 1
  description = "The base size of the Elastic SAN in TiB."
}

variable "elastic_san_volume_size_in_gib" {
  type        = number
  default     = 1
  description = "The size of the Elastic SAN volume in GiB."
}
